  t669: { ca: "<strong>Descomptes per volum:</strong> -5% des de 5 unitats · -10% des de 10 · -15% des de 20 (s'aplica automàticament al cistell).", es: '<strong>Descuentos por volumen:</strong> -5% desde 5 unidades · -10% desde 10 · -15% desde 20 (se aplica automáticamente al carrito).', en: '<strong>Volume discounts:</strong> -5% from 5 units · -10% from 10 · -15% from 20 (applied automatically to your cart).', fr: "<strong>Remises sur volume :</strong> -5% dès 5 unités · -10% dès 10 · -15% dès 20 (appliquées automatiquement au panier).", de: '<strong>Mengenrabatte:</strong> -5% ab 5 Einheiten · -10% ab 10 · -15% ab 20 (wird automatisch im Warenkorb angewendet).', ar: '<strong>خصومات الكميات:</strong> -5% من 5 وحدات · -10% من 10 · -15% من 20 (تُطبَّق تلقائيًا في سلتك).' },
