  t698: { ca: '15% de descompte + condicions de pagament a mida + accés anticipat a nous llançaments.', es: '15% de descuento + condiciones de pago a medida + acceso anticipado a nuevos lanzamientos.', en: '15% discount + tailored payment terms + early access to new launches.', fr: '15 % de remise + conditions de paiement sur mesure + accès anticipé aux nouveautés.', de: '15% Rabatt + maßgeschneiderte Zahlungsbedingungen + Frühzugang zu Neuheiten.', ar: 'خصم 15% + شروط دفع مخصصة + وصول مبكر إلى الإطلاقات الجديدة.' },
  t699: { ca: 'Recorda: el simulador de comanda recurrent suma punts automàticament cada vegada que es processa una reposició programada.', es: 'Recuerda: el simulador de pedido recurrente suma puntos automáticamente cada vez que se procesa una reposición programada.', en: 'Remember: the recurring order simulator adds points automatically every time a scheduled restock is processed.', fr: "N'oubliez pas : le simulateur de commande récurrente ajoute des points automatiquement à chaque réapprovisionnement programmé traité.", de: 'Denken Sie daran: Der Simulator für wiederkehrende Bestellungen vergibt automatisch Punkte bei jeder verarbeiteten geplanten Nachbestellung.', ar: 'تذكير: يضيف محاكي الطلبات المتكررة النقاط تلقائيًا في كل مرة تُعالَج فيها عملية إعادة تزويد مجدولة.' },
  t700: { ca: 'Garanties i Devolucions', es: 'Garantías y Devoluciones', en: 'Warranty & Returns', fr: 'Garanties et Retours', de: 'Garantie und Rückgabe', ar: 'الضمان والإرجاع' },
  t701: { ca: 'Compromís total amb la qualitat: si un producte no compleix les especificacions, ho solucionem.', es: 'Compromiso total con la calidad: si un producto no cumple las especificaciones, lo solucionamos.', en: "Total commitment to quality: if a product doesn't meet specifications, we fix it.", fr: 'Engagement total envers la qualité : si un produit ne répond pas aux spécifications, nous le résolvons.', de: 'Volles Engagement für Qualität: Wenn ein Produkt nicht den Spezifikationen entspricht, lösen wir das Problem.', ar: 'التزام كامل بالجودة: إذا لم يطابق منتجٌ المواصفات، نصلح الأمر.' },
  t702: { ca: 'Garantia de qualitat 100%', es: 'Garantía de calidad 100%', en: '100% Quality Guarantee', fr: 'Garantie de qualité 100 %', de: '100% Qualitätsgarantie', ar: 'ضمان جودة 100%' },
  t703: { ca: "Tots els lots passen control de qualitat certificat abans d'expedir-se. Si detectes cap incidència, ho reportes des del teu compte i el resolem en 48h.", es: 'Todos los lotes pasan control de calidad certificado antes de expedirse. Si detectas cualquier incidencia, la reportas desde tu cuenta y la resolvemos en 48h.', en: "All batches undergo certified quality control before shipping. If you notice any issue, report it from your account and we'll resolve it within 48h.", fr: 'Tous les lots passent un contrôle qualité certifié avant expédition. En cas de problème, signalez-le depuis votre compte et nous le résolvons sous 48h.', de: 'Alle Chargen durchlaufen eine zertifizierte Qualitätskontrolle vor dem Versand. Bei Problemen melden Sie diese über Ihr Konto und wir lösen sie innerhalb von 48h.', ar: 'تخضع جميع الدفعات لرقابة جودة معتمدة قبل الشحن. إذا لاحظت أي مشكلة، أبلغ عنها من حسابك وسنحلّها خلال 48 ساعة.' },
  t704: { ca: '14 dies per a devolucions', es: '14 días para devoluciones', en: '14 Days for Returns', fr: '14 jours pour les retours', de: '14 Tage Rückgaberecht', ar: '14 يومًا للإرجاع' },
  t705: { ca: 'Envasos sense obrir es poden retornar en un termini de 14 dies naturals des de la recepció, sense cap cost per al client.', es: 'Los envases sin abrir se pueden devolver en un plazo de 14 días naturales desde la recepción, sin ningún coste para el cliente.', en: 'Unopened containers can be returned within 14 calendar days of receipt, at no cost to the customer.', fr: 'Les emballages non ouverts peuvent être retournés dans un délai de 14 jours calendaires à compter de la réception, sans frais pour le client.', de: 'Ungeöffnete Behälter können innerhalb von 14 Kalendertagen nach Erhalt kostenlos zurückgegeben werden.', ar: 'يمكن إرجاع العبوات غير المفتوحة خلال 14 يومًا من الاستلام، دون أي تكلفة على العميل.' },
  t706: { ca: 'Reposició immediata', es: 'Reposición inmediata', en: 'Immediate Replacement', fr: 'Remplacement immédiat', de: 'Sofortiger Ersatz', ar: 'استبدال فوري' },
  t707: { ca: 'Producte danyat en transport o error en la comanda: enviem la reposició en 24-48h sense esperar la devolució física.', es: 'Producto dañado en transporte o error en el pedido: enviamos la reposición en 24-48h sin esperar la devolución física.', en: 'Product damaged in transit or order error: we send the replacement within 24-48h without waiting for the physical return.', fr: 'Produit endommagé pendant le transport ou erreur de commande : nous envoyons le remplacement sous 24-48h sans attendre le retour physique.', de: 'Produkt beim Transport beschädigt oder Bestellfehler: Wir senden den Ersatz innerhalb von 24-48h, ohne auf die physische Rücksendung zu warten.', ar: 'منتج متضرر أثناء النقل أو خطأ في الطلب: نرسل البديل خلال 24-48 ساعة دون انتظار الإرجاع الفعلي.' },
  t708: { ca: 'Suport tècnic dedicat', es: 'Soporte técnico dedicado', en: 'Dedicated Technical Support', fr: 'Support technique dédié', de: 'Dedizierter technischer Support', ar: 'دعم تقني مخصص' },
  t709: { ca: 'Dubtes sobre dosificació, compatibilitat o ús del producte? El nostre equip tècnic respon en menys de 24h laborables.', es: '¿Dudas sobre dosificación, compatibilidad o uso del producto? Nuestro equipo técnico responde en menos de 24h laborables.', en: 'Questions about dosage, compatibility or product use? Our technical team responds within 24 business hours.', fr: "Des questions sur le dosage, la compatibilité ou l'utilisation du produit ? Notre équipe technique répond en moins de 24h ouvrées.", de: 'Fragen zu Dosierung, Kompatibilität oder Produktverwendung? Unser technisches Team antwortet innerhalb von 24 Werkstunden.', ar: 'أسئلة حول الجرعة أو التوافق أو استخدام المنتج؟ يرد فريقنا التقني خلال 24 ساعة عمل.' },
  t710: { ca: 'Per iniciar una devolució o reportar una incidència, contacta amb nosaltres indicant el número de comanda.', es: 'Para iniciar una devolución o reportar una incidencia, contacta con nosotros indicando el número de pedido.', en: 'To start a return or report an issue, contact us with your order number.', fr: 'Pour lancer un retour ou signaler un problème, contactez-nous en indiquant le numéro de commande.', de: 'Um eine Rückgabe zu starten oder ein Problem zu melden, kontaktieren Sie uns mit Ihrer Bestellnummer.', ar: 'لبدء إرجاع أو الإبلاغ عن مشكلة، تواصل معنا مع رقم طلبك.' },
