  t869: { ca: 'Captació i seguiment de clients hospitalaris i sociosanitaris a la Comunitat Valenciana. Es valora experiència en el sector.', es: 'Captación y seguimiento de clientes hospitalarios y sociosanitarios en la Comunitat Valenciana. Se valora experiencia en el sector.', en: 'Acquisition and management of hospital and healthcare clients in the Valencian Community. Sector experience is valued.', fr: 'Acquisition et suivi de clients hospitaliers et médico-sociaux dans la Communauté valencienne. Expérience dans le secteur appréciée.', de: 'Gewinnung und Betreuung von Kliniken und Pflegeeinrichtungen in der Region Valencia. Branchenerfahrung von Vorteil.', ar: 'استقطاب وإدارة عملاء المستشفيات والرعاية الصحية في منطقة فالنسيا. تُقدَّر الخبرة في القطاع.' },
  t870: { ca: '📍 València (amb desplaçaments) · Jornada completa', es: '📍 Valencia (con desplazamientos) · Jornada completa', en: '📍 Valencia (with travel) · Full-time', fr: '📍 Valence (déplacements) · Temps plein', de: '📍 Valencia (mit Reisetätigkeit) · Vollzeit', ar: '📍 فالنسيا (مع تنقلات) · دوام كامل' },
  t871: { ca: 'Conductor/a Repartiment', es: 'Conductor/a de Reparto', en: 'Delivery Driver', fr: 'Chauffeur(se)-livreur(se)', de: 'Auslieferungsfahrer/in', ar: 'سائق توصيل' },
  t872: { ca: 'Repartiment amb flota pròpia per València, Castelló i Alacant. Carnet C valorable, no imprescindible.', es: 'Reparto con flota propia por Valencia, Castellón y Alicante. Carnet C valorable, no imprescindible.', en: 'Delivery using our own fleet across Valencia, Castellón and Alicante. Category C licence a plus, not required.', fr: 'Livraisons avec flotte propre à Valence, Castellón et Alicante. Permis C apprécié, non obligatoire.', de: 'Auslieferung mit eigener Flotte in Valencia, Castellón und Alicante. Führerschein Klasse C von Vorteil, nicht erforderlich.', ar: 'التوصيل بأسطولنا الخاص في فالنسيا وكاستيون وأليكانتي. رخصة الفئة C ميزة إضافية وليست شرطًا.' },
  t873: { ca: "Tècnic/a d'Atenció al Client", es: 'Técnico/a de Atención al Cliente', en: 'Customer Service Technician', fr: 'Technicien(ne) service client', de: 'Kundendiensttechniker/in', ar: 'فنّي خدمة العملاء' },
  t874: { ca: 'Gestió de comandes, incidències i seguiment postvenda. Bon tracte telefònic i orientació a la resolució.', es: 'Gestión de pedidos, incidencias y seguimiento postventa. Buen trato telefónico y orientación a la resolución.', en: 'Managing orders, issues and after-sales follow-up. Good phone manner and a problem-solving attitude.', fr: 'Gestion des commandes, incidents et suivi après-vente. Bon relationnel téléphonique et sens de la résolution.', de: 'Verwaltung von Bestellungen, Reklamationen und Nachbetreuung. Gutes Telefonverhalten und Lösungsorientierung.', ar: 'إدارة الطلبات والحوادث ومتابعة ما بعد البيع. لباقة في التعامل الهاتفي وروح لحل المشكلات.' },
  t875: { ca: "No trobes la vacant ideal? Envia'ns igualment la teva candidatura: valorem cada perfil per a futures incorporacions.", es: '¿No encuentras la vacante ideal? Envíanos igualmente tu candidatura: valoramos cada perfil para futuras incorporaciones.', en: "Can't find the right vacancy? Send us your application anyway — we consider every profile for future openings.", fr: 'Vous ne trouvez pas le poste idéal ? Envoyez-nous quand même votre candidature : nous étudions chaque profil pour de futurs recrutements.', de: 'Keine passende Stelle gefunden? Senden Sie uns trotzdem Ihre Bewerbung — wir prüfen jedes Profil für zukünftige Einstellungen.', ar: 'لم تجد الوظيفة المناسبة؟ أرسل لنا طلبك على أي حال — ندرس كل الملفات للفرص المستقبلية.' },
  t876: { ca: "Envia'ns la teva candidatura", es: 'Envíanos tu candidatura', en: 'Send Us Your Application', fr: 'Envoyez-nous votre candidature', de: 'Senden Sie uns Ihre Bewerbung', ar: 'أرسل لنا طلبك' },
  t877: { ca: 'Nom i Cognoms *', es: 'Nombre y Apellidos *', en: 'Full Name *', fr: 'Nom et Prénom *', de: 'Vor- und Nachname *', ar: 'الاسم الكامل *' },
